<script setup>
import { ref,watch,onBeforeUnmount,computed,inject } from 'vue';
import {agentReportKey} from '../../lib/cc-agent-report-context';
import { useRoute } from 'vue-router';
import { watchVisibleReport } from '../../lib/cc-visible-report';
import { requestReportActivity } from '../../api/cc-report-activity';
import { downloadCsv } from '../../lib/cc';
import CCReportHistory from './CCReportHistory.vue';
import CCDataTable from './CCDataTable.vue';
const props=defineProps({from:String,to:String,channel:{type:String,default:'all'},refreshKey:{type:Number,default:0}});const emit=defineEmits(['open','loaded']);
const route=useRoute(),context=inject(agentReportKey,null);
const selection=computed(()=>{const scope=context?.agentScope?.value;return scope?.mode==='single'&&scope.single?[scope.single]:scope?.mode==='multi'?scope.multiple:[];});
const visible=()=>Boolean(route.meta.standaloneAgent360||route.meta.reportTab==='agent360'||(route.meta.reportTab==='agents'&&route.meta.agentSubtab==='convox'));
const historySelection=ref(null);
function openHistory(kind,owner=agent.value){historySelection.value={kind,agent:owner};}
const data=ref(null),busy=ref(false),error=ref(''),gap=ref(15),agent=ref(''),selected=ref(null);let generation=0,controller;
const rows=computed(()=>(data.value?.rows||[]).filter(row=>!agent.value||row.agent===agent.value));
const columns=[{key:'name',label:'Agent'},{key:'convox',label:'ConVox calls'},{key:'mobile',label:'Mobile calls'},{key:'answered',label:'Answered'},{key:'talk',label:'Talk (minutes)',value:r=>(r.talk/60).toFixed(1)},{key:'appointments',label:'Appointments'},{key:'walkins',label:'Walk-ins'},{key:'booked',label:'Booked'},{key:'updates',label:'Lead updates'},{key:'idle_minutes',label:'Idle minutes'},{key:'updated_no_call',label:'Updated, no call'},{key:'talked_no_update',label:'Talked, no update'},{key:'appointment_without_booking',label:'Appt disposition, no appt'}];
const metricLabel=key=>({convox:'ConVox calls',mobile:'Mobile calls',answered:'Answered',talk:'Talk minutes',appointments:'Appointments',walkins:'Walk-ins',booked:'Booked',updates:'Lead updates',idle_minutes:'Idle minutes',updated_no_call:'Updated, no call',talked_no_update:'Talked, no update',appointment_without_booking:'Appointment disposition, no booking'})[key]||key;
const totals=computed(()=>rows.value.reduce((out,row)=>{for(const key of ['convox','mobile','answered','talk','appointments','walkins','booked','updates','idle_minutes','updated_no_call','talked_no_update','appointment_without_booking'])out[key]=(out[key]||0)+(Number(row[key])||0);return out;},{}));
const dayTimeline=computed(()=>{
 if(!data.value?.timeline_available||props.from!==props.to)return [];
 const start=9*60,end=22*60,span=end-start;
 return rows.value.filter(row=>row.events?.length).map(row=>({
  ...row,
  points:row.events.map((event,index)=>{
   const match=String(event.at||'').match(/(?:T|\s)(\d{2}):(\d{2})/);
   const minute=match?Number(match[1])*60+Number(match[2]):start;
   return {...event,index,left:Math.max(0,Math.min(100,(minute-start)*100/span))};
  }).filter(event=>event.left>=0&&event.left<=100)
 }));
});
const timeText=value=>String(value||'').replace('T',' ').slice(11,16)||'—';
async function load(refresh=false){const token=++generation;controller?.abort();controller=new AbortController();busy.value=true;error.value='';data.value=null;selected.value=null;try{const result=await requestReportActivity({agents:JSON.stringify(selection.value),from_date:props.from,to_date:props.to,gap:gap.value,channel:props.channel},controller.signal,refresh);if(token===generation){data.value=result;emit('loaded',result);}}catch(e){if(token===generation&&e.name!=='AbortError')error.value=e.message;}finally{if(token===generation)busy.value=false;}}
watch(agent,()=>{if(data.value)emit('loaded',{...data.value,rows:rows.value});});
let previousRefresh=props.refreshKey;
watchVisibleReport(()=>[props.from,props.to,props.channel,props.refreshKey,selection.value.join('|')],visible,async()=>{const refresh=previousRefresh!==props.refreshKey;previousRefresh=props.refreshKey;await load(refresh);},()=>!!data.value&&!error.value);onBeforeUnmount(()=>{generation++;controller?.abort();});
function exportRows(){if(data.value&&!data.value.capped)downloadCsv('cc-call-activity.csv',columns,rows.value);}
</script>
<template><section class="cc-card"><h2>{{channel==='convox'?'ConVox disposition report':'Agent 360 · ConVox + Mobile + ERP activity'}}</h2><div class="cc-filters"><label>Agent<select v-model="agent"><option value="">All permitted agents</option><option v-for="row in data?.rows||[]" :key="row.agent" :value="row.agent">{{row.name}}</option></select></label><label>Idle gap<select v-model.number="gap" @change="load(true)"><option v-for="n in [10,15,20,30]" :key="n" :value="n">{{n}} minutes</option></select></label><button :disabled="busy" @click="load(true)">Refresh activity</button><button :disabled="!data||data.capped" @click="exportRows">Export activity CSV</button></div><p v-if="error" class="cc-error" role="alert">{{error}}</p><p v-for="warning in data?.warnings||[]" :key="warning" role="status">{{warning}}</p><p v-if="data?.capped" class="cc-error">Partial activity data. Narrow the date range before exporting.</p><p v-if="data&&!data.timeline_available">Timeline, idle gaps and mismatch checks require a range of seven days or less.</p><div class="cc-report-metrics"><button v-for="(value,key) in totals" :key="key" class="cc-history-card" :disabled="['appointments','walkins','booked','idle_minutes'].includes(key)" @click="openHistory(['updates','updated_no_call','talked_no_update','appointment_without_booking'].includes(key)?'updates':key==='mobile'?'mobile':'convox')"><strong>{{key==='talk'?(value/60).toFixed(1):value}}</strong><span>{{metricLabel(key)}}</span></button></div><section v-if="dayTimeline.length" class="cc-day-timeline"><header><h3>Day timeline</h3><small>{{from}} · calls and lead updates, 9:00 am–10:00 pm</small></header><div class="cc-timeline-axis" aria-hidden="true"><span v-for="hour in [9,11,13,15,17,19,21]" :key="hour" :style="{left:((hour-9)/13*100)+'%'}">{{hour>12?hour-12:hour}}{{hour<12?'am':'pm'}}</span></div><div v-for="row in dayTimeline" :key="row.agent" class="cc-timeline-row"><button class="cc-timeline-agent" @click="selected=row">{{row.name}}</button><div class="cc-timeline-track"><button v-for="event in row.points" :key="event.index" class="cc-timeline-point" :class="'is-'+event.channel" :style="{left:event.left+'%'}" :title="timeText(event.at)+' · '+(event.disposition||event.status||event.channel)" @click="selected=row"></button></div></div><p class="cc-timeline-legend"><i class="is-convox"></i> ConVox <i class="is-mobile"></i> Mobile <i class="is-update"></i> Lead update</p></section><CCDataTable :columns="columns" :rows="rows" :busy="busy"><template #cell-convox="{row}"><button class="cc-history-count" @click="openHistory('convox',row.agent)">{{row.convox}}</button></template><template #cell-mobile="{row}"><button class="cc-history-count" @click="openHistory('mobile',row.agent)">{{row.mobile}}</button></template><template #actions="{row}"><button @click="openHistory('updates',row.agent)">Lead updates</button><button @click="selected=row">Timeline / outcomes</button></template></CCDataTable><section v-if="selected"><h3>{{selected.name}} · Call outcomes</h3><p v-if="selected.timeline_truncated" class="cc-error">Showing the first 1,000 timeline events. Narrow the range for full detail.</p><button @click="selected=null">Close details</button><p v-for="(count,outcome) in selected.dispositions" :key="outcome">{{outcome}}: {{count}}</p><div class="cc-table"><table><thead><tr><th>Time</th><th>Channel</th><th>Lead</th><th>Outcome</th><th>Talk seconds</th></tr></thead><tbody><tr v-for="(event,i) in selected.events" :key="i"><td>{{event.at}}</td><td>{{event.channel}}</td><td><button v-if="event.lead" @click="emit('open',event.lead)">{{event.lead}}</button></td><td>{{event.disposition||event.status}}</td><td>{{event.talk}}</td></tr></tbody></table></div></section><CCReportHistory v-if="historySelection" :from="from" :to="to" :selection="historySelection" @close="historySelection=null" @open="id=>{historySelection=null;emit('open',id)}"/></section></template>

<style scoped>.cc-history-card{display:grid;gap:6px;min-height:79px;padding:15px;border:1px solid #d4e2d7;border-radius:11px;background:linear-gradient(145deg,#fff,#f3f8f4);color:#174b30;cursor:pointer;text-align:left;transition:transform .15s,box-shadow .15s,border-color .15s}.cc-history-card strong{font-size:24px;line-height:1}.cc-history-card span{color:#587061;font-size:12px;font-weight:700}.cc-history-card:hover:not(:disabled){border-color:#4b9867;box-shadow:0 6px 14px #174b3014;transform:translateY(-1px)}.cc-history-card:disabled{cursor:default;opacity:1}.cc-history-count{border:0;background:transparent;color:#175a37;text-decoration:underline;font:inherit;font-weight:700;cursor:pointer}.cc-day-timeline{margin:22px 0;padding:18px;border:1px solid #d8e5db;border-radius:13px;background:linear-gradient(145deg,#f8fcf9,#fff);overflow:auto}.cc-day-timeline header{display:flex;align-items:baseline;justify-content:space-between;gap:12px;flex-wrap:wrap;padding-bottom:12px;border-bottom:1px solid #e6eee8}.cc-day-timeline h3{margin:0;color:#173d2b;font-size:17px}.cc-day-timeline small{color:#617467}.cc-timeline-axis,.cc-timeline-track{position:relative;min-width:680px}.cc-timeline-axis{height:29px;margin:14px 0 0 158px;border-top:1px solid #bfcebf}.cc-timeline-axis span{position:absolute;top:6px;transform:translateX(-50%);font-size:11px;color:#617467}.cc-timeline-row{display:grid;grid-template-columns:148px minmax(540px,1fr);gap:10px;align-items:center;margin:9px 0}.cc-timeline-agent{border:0;background:transparent;color:#174b30;text-align:right;text-decoration:underline;font:inherit;font-weight:750;cursor:pointer;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.cc-timeline-track{height:27px;background:repeating-linear-gradient(90deg,#eef5ef 0,#eef5ef calc(7.69% - 1px),#d9e7db calc(7.69% - 1px),#d9e7db 7.69%);border:1px solid #e0ebe2;border-radius:7px}.cc-timeline-point{position:absolute;top:6px;width:14px;height:14px;padding:0;transform:translateX(-50%);border:2px solid white;border-radius:50%;box-shadow:0 1px 3px #123b252b;cursor:pointer}.cc-timeline-point:hover{z-index:2;transform:translateX(-50%) scale(1.28)}.cc-timeline-point.is-convox,.cc-timeline-legend .is-convox{background:#2463a5}.cc-timeline-point.is-mobile,.cc-timeline-legend .is-mobile{background:#16806e}.cc-timeline-point.is-update,.cc-timeline-legend .is-update{background:#bd8622}.cc-timeline-legend{margin:14px 0 0 158px;font-size:12px;color:#617467}.cc-timeline-legend i{display:inline-block;width:10px;height:10px;border-radius:50%;margin:0 4px 0 12px}@media(max-width:750px){.cc-day-timeline{padding:13px}.cc-timeline-axis{margin-left:110px}.cc-timeline-row{grid-template-columns:100px minmax(540px,1fr)}.cc-timeline-legend{margin-left:100px}}</style>
